# -*- coding: utf-8 -*-
import re
p='src/lalka-2/work/chapter-01/scaffold.txt'
t={225:'— Або, — провадила баронеса, — пан Вокульський усуне зі свого дому цей бруд і розпусту...',226:'— Розпусту? — спитав я.',227:'— Так, пане, — підтвердила баронеса, киваючи головою. — Ті пралі, що цілими днями співають унизу якісь огидні пісеньки, а ввечері регочуть у мене над головою в тих... студентів... Ті злочинці, що кидають на мене згори недопалки або ллють воду...',228:'А ще пані Ставська, про яку я й не знаю, хто вона: вдова чи розлучена, і з чого живе... Ця пані відбиває чоловіків у доброчесних дружин, таких нещасних...',229:'Вона заморгала й розплакалася.',230:'— Жах!... — схлипувала вона. — Бути прикованою до такого огидного дому пам’яттю про дитину, якої ніщо вже не вирве з мого серця. Адже вона бігала по всіх цих кімнатах... Гралася там, з боку подвір’я... І визирала у вікно, з якого мені, матері-сироті, сьогодні не дозволено виглянути...',231:'Мене хочуть звідси вигнати... усі хочуть мене вигнати... я всім заважаю... А я ж не можу звідси виїхати, бо кожна дошка цієї підлоги зберігає слід її ніжок... у кожній стіні застряг її сміх чи плач...',232:'Вона впала на канапу й зайшлася риданням.',233:'— Ах! — плакала вона. — Люди жорстокіші за звірів... Хочуть вигнати мене звідси, де моя дитинка віддала останній подих... Її ліжечко й усі іграшки лежать на своїх місцях... Я сама витираю пил у її кімнаті, щоб не зрушити найменшої речі...',234:'Кожен дюйм<sup>595</sup> підлоги я витоптала колінами, цілувала сліди моєї дитинки, а вони хочуть мене вигнати!... Спершу виженіть звідси мій біль, тугу, розпач...',235:'Вона затулила обличчя й ридала нестямно. Я помітив, що в управителя почервонів ніс, а й сам відчув сльози під повіками.',236:'Розпач баронеси за померлою дитиною так мене обеззброїв, що я не мав відваги говорити з нею про підвищення квартирної плати. А її плач так мене нервував, що, якби не другий поверх, я, мабуть, вистрибнув би у вікно.',237:'Зрештою, бажаючи будь-що втішити жінку, що ридала, я якомога лагідніше озвався:',238:'— Пані, заспокойтеся... Чого ви від нас хочете?... Чим можемо прислужитися?...',239:'У моєму голосі було стільки співчуття, що ніс управителя почервонів ще дужче. У баронеси ж одне око висохло, а другим вона й далі плакала — на знак, що не вважає свою виставу закінченою, а мене переможеним.',240:'— Вимагаю... вимагаю, — мовила вона крізь зітхання, — щоб мене не виганяли з місця, де померла моя дитина... де все мені про неї нагадує. Не можу, ну... не можу відірватися від її кімнати... не можу пересунути її речі та іграшки... Підло так користатися з чужого горя.',241:'— Хто ж користається? — спитав я.',242:'— Усі, починаючи з господаря, який вимагає з мене сімсот рублів...',243:'— Ах, перепрошую, пані баронесо! — вигукнув управитель. — Сім чудових кімнат, дві кухні, мов вітальні, дві комори... Віддайте комусь бодай три кімнати: у вас же два виходи на фасад.',244:'— Нікому нічого не віддам, — рішуче відповіла вона, — бо певна, що мій чоловік, який заблукав, ось-ось отямиться й повернеться...'}
lines=open(p,encoding='utf-8').read().splitlines();i=-1;out=[]
for l in lines:
 if l.startswith('**PL:**'):i+=1
 if l=='**UA:**' and i in t:l='**UA:** '+t[i]
 out.append(l)
open(p,'w',encoding='utf-8').write('\n'.join(out));print('filled',len(t))
